window.docContents[133].resolve({"/rules/RG1005/#RG1005-rationale":{"contents":"A profile claim tells readers which logical principles every result on the surface may use. One declaration above the bound makes the claim false for the whole surface.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG1005: Transitive axioms must fit the selected profile","header":"Why it matters","id":"/rules/RG1005/#RG1005-rationale"},"/rules/RG2004/#RG2004-rationale":{"contents":"A conformance claim covers an exact set of modules. A module imported into a claimed library but outside every surface would contribute declarations nobody classified, and an umbrella import alone does not define that set.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG2004: Owned coverage must match the exact Lake inventory","header":"Why it matters","id":"/rules/RG2004/#RG2004-rationale"},"/rules/RG4002/#RG4002-rationale":{"contents":"Readers copy documented examples and trust them. A positive example that does not elaborate, or that proves its claim with an axiom, teaches a false claim.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG4002: Positive examples require warning-free elaboration and admission","header":"Why it matters","id":"/rules/RG4002/#RG4002-rationale"},"/rules/RG5001/#RG5001-rationale":{"contents":"Module documentation tells a reader which declarations carry the module's claims and under which assumptions, so the claims can be reviewed without reading every proof.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG5001: Claimed modules require module documentation","header":"Why it matters","id":"/rules/RG5001/#RG5001-rationale"}});